if '</head>' not in h or '</body>' not in h:
    raise SystemExit('HTML markers missing')
h=h.replace('</head>',css+'\n</head>',1)
h=h.replace('</body>',js+'\n</body>',1)
p.write_text(h,encoding='utf-8')
